const char* LevelTools_getAudioTitle(int id) {
    switch (id) {
        case -1: return "Practice: Stay Inside Me";
        case 0: return "Stereo Madness";
        case 1: return "Back On Track";
        case 2: return "Polargeist";
        case 3: return "Dry Out";
        case 4: return "Base After Base";
        case 5: return "Cant Let Go";
        case 6: return "Jumper";
        case 7: return "Time Machine";
        case 8: return "Cycles";
        case 9: return "xStep";
        case 10: return "Clutterfunk";
        case 11: return "Theory Of Everything";
        case 12: return "Electroman Adventures";
        case 13: return "Clubstep";
        case 14: return "Electrodynamix";
        case 15: return "Tiny Tunes";
        case 16: return "Techno Reactor";
        case 17: return "This Isnt Science Rocket";
        case 18: return "Captain Cool";
        case 19: return "Stereo Madness 2";
        case 20: return "Infernoplex";
        case 21: return "The Power";
        case 22: return "Stalemate";
        case 23: return "Beep Beep";
        case 24: return "Uprise";
        case 25: return "Radioactive";
        case 26: return "Eurodancer";
        case 27: return "Mega Tsunami";
        case 28: return "Final Battle";
        case 29: return "Sphere";
        default: return "Silent Clubstep";
    }
}
