int LevelTools_artistForAudio(int id) {
    int aToS[30] = {3, 0, 4, 0, 0, 0, 1, 1, 0, 0, 1, 5, 1, 5, 5, 7, 0, 6, 9, 3, 8, 5, 10, 11, 12, 1, 13, 2, 1, 14};
    if (id == -1) return 2;
    if (id > 30) return 0;
    return aToS[id];
}

