const char* LevelTools_nameForArtist(int id) {
    switch (id) {
        case 0: return "DJVI";
        case 1: return "Waterflame";
        case 2: return "OcularNebula";
        case 3: return "ForeverBound";
        case 4: return "Step";
        case 5: return "DJ-Nate";
        case 6: return "F-777";
        case 7: return "Fantomenk";
        case 8: return "Dimrain47";
        case 9: return "Bossfight";
        case 10: return "Kayoszk";
        case 11: return "Schtiffles";
        case 12: return "EnVy";
        case 13: return "TMM43";
        case 14: return "Creo";
        default: return "Unknown";
    }
}

void GDPS17_patch() {
    // Editor song selection
    DobbyCodePatch(reinterpret_cast<void*>(get_address(0x199c94)), std::vector<uint8_t>({0x1d}).data(), 1);
    DobbyCodePatch(reinterpret_cast<void*>(get_address(0x199c48)), std::vector<uint8_t>({0x1d}).data(), 1);
    DobbyCodePatch(reinterpret_cast<void*>(get_address(0x199c4c)), std::vector<uint8_t>({0x1d}).data(), 1);

    // Search filter
    DobbyCodePatch(reinterpret_cast<void*>(get_address(0x1a4ef0)), std::vector<uint8_t>({0x1e}).data(), 1);
    DobbyCodePatch(reinterpret_cast<void*>(get_address(0x1a4e8c)), std::vector<uint8_t>({0x1e}).data(), 1);
    DobbyCodePatch(reinterpret_cast<void*>(get_address(0x1a4e92)), std::vector<uint8_t>({0x1e}).data(), 1);

    // Song info in LevelSelectLayer
    DobbyCodePatch(reinterpret_cast<void*>(get_address(0x1c2a80)), std::vector<uint8_t>({0x1e}).data(), 1);
}

void GDPS17_om() {
    Omni::hook("_ZN10LevelTools13getAudioTitleEi",
        reinterpret_cast<void*>(LevelTools_getAudioTitle), nullptr);
    Omni::hook("_ZN10LevelTools16getAudioFileNameEi",
        reinterpret_cast<void*>(LevelTools_getAudioFileName), nullptr);
    Omni::hook("_ZN10LevelTools14getAudioStringEi",
        reinterpret_cast<void*>(LevelTools_getAudioString), nullptr);
    Omni::hook("_ZN10LevelTools14artistForAudioEi",
        reinterpret_cast<void*>(LevelTools_artistForAudio), nullptr);
    Omni::hook("_ZN10LevelTools13nameForArtistEi",
        reinterpret_cast<void*>(LevelTools_nameForArtist), nullptr);

    GDPS17_patch();
}